insert into practice_context_blocks (id, exercise_id, label, image_url, text_content, block_type) values
  ('4c53767e-ad8b-43b1-8cf4-b66518d24891', '1577ca6a-6e0b-45a7-963d-5791c1ce2a96', $$inleiding: Kevin krijgt na maagverkleiningsoperatie het darmfermentatiesyndroom (DFS)$$,
   $$biologie-vwo-2025-ii-een-brouwerij-in-de-darmen-context1.png$$,
   $$Kevin raakte betrokken bij een auto-ongeluk. Hoewel hij geen alcohol had gedronken, was zijn alcoholpromillage gelijk aan dat na het drinken van elf glazen bier. Na onderzoek bleek hij het darmfermentatie-syndroom (DFS) te hebben.$$, 'inline'),
  ('e595adab-f955-4883-bd39-b186c0662eda', '1577ca6a-6e0b-45a7-963d-5791c1ce2a96', $$informatiekader: mini-maag na maagverkleiningsoperatie (afbeelding 1)$$,
   $$biologie-vwo-2025-ii-een-brouwerij-in-de-darmen-context2.png$$,
   $$Kevin heeft een aantal jaren voor het auto-ongeluk een maagverkleiningsoperatie gehad. Bij deze operatie wordt het bovenste gedeelte van de maag verbonden aan een deel van de dunne darm dat na de twaalfvingerige darm komt. Zo ontstaat een mini-maag (afbeelding 1). Het resterende gedeelte van de maag en de twaalfvingerige darm blijven in het lichaam achter, en worden verbonden met de dunne darm. Door de maagverkleining is het deel van de dunne darm waar voedingstoffen en alvleesklier-enzymen gelijktijdig aanwezig zijn, anderhalve meter korter.
afbeelding 1$$, 'inline'),
  ('23ee8d73-9aee-47ca-b70a-e851aad517fe', '1577ca6a-6e0b-45a7-963d-5791c1ce2a96', $$gewichtsverlies na maagverkleining heeft verschillende oorzaken (informatiekader)$$,
   $$biologie-vwo-2025-ii-een-brouwerij-in-de-darmen-context3.png$$,
   $$Mensen die een maagverkleining hebben ondergaan, verliezen daarna snel gewicht. Hiervoor zijn verschillende oorzaken, die zijn af te leiden uit de gegevens in het informatiekader.$$, 'inline'),
  ('037667a9-2436-4fb9-8436-4f85b2eebd95', '1577ca6a-6e0b-45a7-963d-5791c1ce2a96', $$informatiekader: gastrine en de pH van de maag (afbeelding 2)$$,
   $$biologie-vwo-2025-ii-een-brouwerij-in-de-darmen-context4.png$$,
   $$Door Kevins maagverkleiningsoperatie wordt de gastrine-concentratie in zijn bloed beïnvloed, waardoor ook de productie van maagzuur door de pariëtale cellen verandert. Gastrine wordt geproduceerd door gastrine-cellen die zich bevinden in de wand van het onderste gedeelte van de maag en in de wand van de twaalfvingerige darm. In afbeelding 2 is vereenvoudigd weergegeven hoe gastrine de pH van de maag beïnvloedt.
afbeelding 2$$, 'inline'),
  ('420f8a50-38c6-4e87-98a9-40c69bac1834', '1577ca6a-6e0b-45a7-963d-5791c1ce2a96', $$pH in de mini-maag van Kevin is hoger dan normaal$$,
   $$biologie-vwo-2025-ii-een-brouwerij-in-de-darmen-context5.png$$,
   $$In de mini-maag van Kevin is de pH hoger dan bij mensen zonder maagverkleiningsoperatie.$$, 'inline'),
  ('9eabf66d-c4e2-4790-8d72-68857416ec93', '1577ca6a-6e0b-45a7-963d-5791c1ce2a96', $$informatiekader: verandering microbioom en ontdekking DFS-bacterie Klebsiella pneumoniae$$,
   $$biologie-vwo-2025-ii-een-brouwerij-in-de-darmen-context6.png$$,
   $$Vaak verandert na een maagverkleining de soortensamenstelling van het microbioom (alle micro-organismen) in de darm. Bij Kevin leidde dit tot het ontstaan van DFS. DFS is een zeer zeldzame aandoening waarbij bepaalde schimmels en bacteriën in de darm glucose omzetten in alcohol. In het ziekenhuis werd bij Kevin in de ontlasting de bacterie Klebsiella pneumoniae aangetoond, die onder bepaalde omstandigheden alcohol produceert. Hiermee kon de diagnose DFS worden gesteld. Na deze diagnose kreeg Kevin een streng koolhydraat-arm dieet en een breed- spectrum-antibioticumkuur. Een breed-spectrum-antibioticum bestrijdt veel verschillende bacteriesoorten.$$, 'inline'),
  ('6e35a76c-6d15-4ff9-8a78-968431cc5f64', '1577ca6a-6e0b-45a7-963d-5791c1ce2a96', $$kans op kolonisatie door schadelijke bacteriën na breed-spectrum-antibioticum$$,
   $$biologie-vwo-2025-ii-een-brouwerij-in-de-darmen-context7.png$$,
   $$Door een behandeling met een breed-spectrum-antibioticum is er een kans dat andere schadelijke bacteriën de darm koloniseren.$$, 'inline'),
  ('41950fcc-d516-4a69-a0d8-e3ffcb89b96a', '489c5522-2f06-4560-b984-edb9fa4f7008', $$inleiding: jakobskruiskruid als geliefde bermplant, maar giftig voor vee$$,
   $$biologie-vwo-2025-ii-jakobskruiskruid-uit-de-berm-context1.png$$,
   $$Jakobskruiskruid is een plant die geliefd is bij bijen en vlinders. De soort wordt daarom veel gebruikt bij ecologisch bermbeheer om bermen mee in te zaaien. Veehouders zijn daar meestal niet blij mee: de plant is namelijk giftig voor runderen en paarden.$$, 'inline'),
  ('c49995e8-1638-4997-b37c-e4e44f1f0c2d', '489c5522-2f06-4560-b984-edb9fa4f7008', $$informatiekader: jakobskruiskruid is een tweejarige pionierplant (afbeelding 1)$$,
   $$biologie-vwo-2025-ii-jakobskruiskruid-uit-de-berm-context2.png$$,
   $$afbeelding 1
Jakobskruiskruid (Jacobaea vulgaris, afbeelding 1) is een inheemse plant die vroeger alleen voorkwam in de duinen. De plant groeit daar op zuidhellingen waar konijnen en zandverstuiving ervoor zorgen dat er weinig begroeiing is. De plant is tweejarig. Hij vormt in het eerste jaar een bladrozet en een groot wortelstelsel. In het tweede jaar komt de plant tot bloei en produceert dan enorm veel pluizige zaden. Hierna sterft de plant af.$$, 'inline'),
  ('03184c23-17e0-4505-bab5-5ebc560db2c2', '489c5522-2f06-4560-b984-edb9fa4f7008', $$informatiekader: vorming en transport van de PA senecionine uit putrescine (afbeelding 2)$$,
   $$biologie-vwo-2025-ii-jakobskruiskruid-uit-de-berm-context3.png$$,
   $$Grazers mijden jakobskruiskruid, afbeelding 2 omdat de plant bittere afweerstoffen tegen vraat produceert. Dit zijn de zogenoemde pyrrolizidine alkaloïden (PA’s). Een van deze PA’s is senecionine. Deze stof wordt gevormd uit de voorloperstof putrescine (afbeelding 2, C₄H₁₂N₂). Senecionine wordt met de organische sapstroom vervoerd naar alle delen van de plant. Daar kan het vervolgens worden omgezet in andere PA’s, die ook via die route worden getransporteerd.$$, 'inline'),
  ('a3532282-94e1-42a8-a998-ed91ce50d8af', '489c5522-2f06-4560-b984-edb9fa4f7008', $$putrescine vereist opname van anorganische bouwstoffen$$,
   $$biologie-vwo-2025-ii-jakobskruiskruid-uit-de-berm-context4.png$$,
   $$Om putrescine te produceren moet een plant ten minste drie verschillende anorganische verbindingen opnemen.$$, 'inline'),
  ('09f60e18-cf32-451a-b609-2bdebdd02706', '489c5522-2f06-4560-b984-edb9fa4f7008', $$drie uitspraken over vorming en transport van senecionine$$,
   $$biologie-vwo-2025-ii-jakobskruiskruid-uit-de-berm-context5.png$$,
   $$Hieronder staan uitspraken over PA’s.
1 Vorming van senecionine uit putrescine is een vorm van stikstofassimilatie.
2 PA’s worden via de bastvaten vervoerd.
3 Transport van PA’s vindt vooral plaats door worteldruk. Schrijf de nummers 1, 2 en 3 onder elkaar. Noteer erachter of de$$, 'inline'),
  ('da22b4ae-76da-4766-9fa4-c550dcac148e', '489c5522-2f06-4560-b984-edb9fa4f7008', $$informatiekader: PA-vergiftiging bij vee door omzetting in pyrrolen in de lever$$,
   $$biologie-vwo-2025-ii-jakobskruiskruid-uit-de-berm-context6.png$$,
   $$Jakobskruiskruid in gedroogde vorm is gevaarlijk voor vee. De plant verliest door drogen zijn bitterheid maar niet zijn giftigheid. Runderen en paarden kunnen de plant, als die gemengd is in hooi, niet onderscheiden. Ze eten de plant met de rest van het hooi. De PA’s uit de plant worden dan opgenomen in het bloed en kunnen worden uitgescheiden door de nieren. De giftigheid ontstaat als levercellen de PA’s omzetten in pyrrolen. Deze stoffen tasten de levercellen aan.$$, 'inline'),
  ('191a21d0-0bfc-4806-8546-886983cfbf81', '489c5522-2f06-4560-b984-edb9fa4f7008', $$pyrrolenvergiftiging veroorzaakt portale hypertensie$$,
   $$biologie-vwo-2025-ii-jakobskruiskruid-uit-de-berm-context7.png$$,
   $$Dieren met vergiftiging door pyrrolen krijgen last van portale hypertensie: een hoge bloeddruk in het poortadersysteem met als gevolg dat vocht vanuit de bloedvaten van de darmen in de buikholte terechtkomt.$$, 'inline'),
  ('83757b0e-0d3c-4f72-bea1-fb4cfca29b25', '489c5522-2f06-4560-b984-edb9fa4f7008', $$informatiekader: verontreinigd maaisel onbruikbaar als veevoer$$,
   $$biologie-vwo-2025-ii-jakobskruiskruid-uit-de-berm-context8.png$$,
   $$Het maaisel uit grasland waar jakobskruiskruid groeit, kan niet meer als voer worden gebruikt. Veehouders eisen daarom dat de overheid het jakobskruiskruid bestrijdt dat in de buurt van hun graslanden groeit.$$, 'inline'),
  ('3453df60-5ab2-4c2b-a5f4-76e4e2b8bf96', '489c5522-2f06-4560-b984-edb9fa4f7008', $$gegevens over dodelijke PA-dosis en PA-concentratie in jakobskruiskruid$$,
   $$biologie-vwo-2025-ii-jakobskruiskruid-uit-de-berm-context9.png$$,
   $$Een gehalte van 2,5 mg PA per kilogram lichaamsgewicht is dodelijk voor koeien. De gemiddelde PA-concentratie in jakobskruiskruid is 0,2% van het drooggewicht van de plant. Veronderstel dat een koe hooi te eten krijgt dat 3% jakobskruiskruid bevat.$$, 'inline'),
  ('f4620444-900f-4a44-a5b4-500322925c17', '489c5522-2f06-4560-b984-edb9fa4f7008', $$informatiekader: specialistische vraatinsecten zebrarups en jakobskruid-aardvlo ongevoelig voor PA’s (afbeelding 3, afbeelding 4)$$,
   $$biologie-vwo-2025-ii-jakobskruiskruid-uit-de-berm-context10.png$$,
   $$Om jakobskruiskruid op een duurzame manier te bestrijden, zou een vraatinsect kunnen worden ingezet dat zich gespecialiseerd heeft op jakobskruiskruid. Voorbeelden hiervan zijn de zebrarups (de geel-zwarte larve van de sint-jakobsvlinder Tyria jacobaeae, afbeelding 3), die algemeen in Nederland voorkomt, en de jakobskruid-aardvlo (Longitarsus jacobaeae, afbeelding 4), die voorkomt in duingebieden in het westen van Nederland.
afbeelding 3 afbeelding 4
Beide soorten zijn ongevoelig voor PA’s. Ze slaan PA’s op in hun lichaam, waardoor ze beschermd zijn tegen natuurlijke vijanden.$$, 'inline'),
  ('99931b46-b64e-4c70-a21f-340506026072', '489c5522-2f06-4560-b984-edb9fa4f7008', $$de sint-jakobsvlinder leeft als rups alleen op jakobskruiskruid$$,
   $$biologie-vwo-2025-ii-jakobskruiskruid-uit-de-berm-context11.png$$,
   $$De sint-jakobsvlinder is zodanig aangepast dat hij als rups alleen nog leeft op jakobskruiskruid.$$, 'inline'),
  ('2fccfe58-8cf7-4dce-8314-b4d4d59b662c', '489c5522-2f06-4560-b984-edb9fa4f7008', $$inzet van specialistische vraatinsecten verandert de concurrentie tussen planten$$,
   $$biologie-vwo-2025-ii-jakobskruiskruid-uit-de-berm-context12.png$$,
   $$Door de inzet van deze specialistische vraatinsecten verandert de concurrentie tussen planten. Welke planten zijn dan in het voordeel? En wat zal dan vervolgens het$$, 'inline'),
  ('4461db87-26f0-48e8-b90b-932baf2c8277', '489c5522-2f06-4560-b984-edb9fa4f7008', $$jakobskruid-aardvlo bestrijdt jakobskruiskruid effectief maar verspreidt zich traag$$,
   $$biologie-vwo-2025-ii-jakobskruiskruid-uit-de-berm-context13.png$$,
   $$De larven van de jakobskruid-aardvlo zijn heel effectief in het bestrijden van jakobskruiskruid. De aardvlo verspreidt zich echter zeer traag. Sommige veehouders planten daarom jakobskruiskruid dat is geïnfecteerd met de jakobskruid-aardvlo op hun weilanden.$$, 'inline'),
  ('5c67875a-5479-49d0-95e1-487de2ba6b4a', 'f582a769-7258-4d17-a9e0-be6f7de3b212', $$inleiding: hogere leeftijd bij eerste kind vergroot kans op chromosomale afwijkingen in eicellen$$,
   $$biologie-vwo-2025-ii-verouderende-eicellen-context1.png$$,
   $$De gemiddelde leeftijd waarop vrouwen in Nederland hun eerste kind krijgen, is in de afgelopen vijftig jaar gestegen van 24 naar 31 jaar. Met de leeftijd neemt de kans op chromosomale afwijkingen in eicellen toe. Wetenschappers hebben onderzocht of het mogelijk is om dit leeftijdseffect te vertragen.$$, 'inline'),
  ('0c157205-0d51-4ac7-aa8f-e32d5cce62f7', 'f582a769-7258-4d17-a9e0-be6f7de3b212', $$informatiekader: trisomie ontstaat door fout tijdens de meiose bij de moeder; stadia oögenese (afbeelding 1)$$,
   $$biologie-vwo-2025-ii-verouderende-eicellen-context2.png$$,
   $$Bij vrouwen boven de 40 jaar is de kans op het ontstaan van een trisomie (een chromosoom extra) bij de bevruchting 30%. Een trisomie bij het embryo leidt meestal tot een miskraam. Trisomie ontstaat in de meeste gevallen door een fout tijdens de meiose bij de moeder. In afbeelding 1 zijn de verschillende stadia tijdens de oögenese en na de bevruchting met cijfers aangegeven.
afbeelding 1$$, 'inline'),
  ('f35f9e14-21dd-4ccd-aff0-7b98f67fb29a', 'f582a769-7258-4d17-a9e0-be6f7de3b212', $$crossing-over verloopt minder goed bij oudere vrouwen$$,
   $$biologie-vwo-2025-ii-verouderende-eicellen-context3.png$$,
   $$Behalve trisomie kunnen er ook andere chromosomale afwijkingen ontstaan. Er zijn een aantal factoren bekend die kunnen bijdragen aan het ontstaan van chromosomale afwijkingen in eicellen. Zo wordt bij oudere vrouwen crossing-over minder goed uitgevoerd. Gedurende welke vorm van deling kan crossing-over leiden tot$$, 'inline'),
  ('91ba016b-8d44-4ec8-bd00-5f16f5141ea7', 'f582a769-7258-4d17-a9e0-be6f7de3b212', $$chromosomale afwijkingen door reactieve zuurstofverbindingen tijdens ovulatie$$,
   $$biologie-vwo-2025-ii-verouderende-eicellen-context4.png$$,
   $$In rustende eicellen kunnen chromosomale afwijkingen worden veroorzaakt door reactieve zuurstofverbindingen. Deze verbindingen ontstaan als gevolg van de weefselschade die optreedt tijdens de ovulatie.$$, 'inline'),
  ('aa77e24d-09bd-443b-8867-53dfb70174cb', 'f582a769-7258-4d17-a9e0-be6f7de3b212', $$informatiekader: hypothese en drie groepen vrouwtjesmuizen in het onderzoek$$,
   $$biologie-vwo-2025-ii-verouderende-eicellen-context5.png$$,
   $$De wetenschappers stelden de volgende hypothese op: de ovulatie- frequentie bepaalt het aantal chromosomale afwijkingen in eicellen. Zij toetsten dit bij drie groepen vrouwtjesmuizen:
1 muizen die voortdurend zwanger waren, doordat er mannetjes aanwezig waren
2 muizen waarbij de ovulaties onderdrukt werden met een hormoon- implantaat
3 muizen waarbij de puberteit geblokkeerd werd met behulp van een crispr-cas-behandeling$$, 'inline'),
  ('f9301b2c-b917-4a98-bbae-4932ea5f7184', 'f582a769-7258-4d17-a9e0-be6f7de3b212', $$muizen in groep 2 kregen implantaat met hormoon dat ovulaties onderdrukt$$,
   $$biologie-vwo-2025-ii-verouderende-eicellen-context6.png$$,
   $$De muizen in groep 2 kregen een implantaat met een hormoon dat ovulaties onderdrukt. Welk hormoon is in het implantaat aanwezig?$$, 'inline'),
  ('a2b831dc-e4e4-4e51-8d47-1febfce7bea9', 'f582a769-7258-4d17-a9e0-be6f7de3b212', $$informatiekader: Gpr54-gen knock-out gemaakt met crispr-cas (afbeelding 2)$$,
   $$biologie-vwo-2025-ii-verouderende-eicellen-context7.png$$,
   $$De puberteit van de muizen in groep 3 werd geblokkeerd door het gen Gpr54 knock-out te maken. Normaal zorgt dit gen ervoor dat de muizen geslachtsrijp worden. Met behulp van de crispr-cas-techniek werd midden in exon 1 een stuk van 67 baseparen ‘weggeknipt’, waardoor het gevormde eiwit niet functioneel is. Het bewerkte allel noteren we als Gpr54⁻, het normale allel als Gpr54⁺. In afbeelding 2 is het gen Gpr54 met daarin de vijf exons weergegeven.
afbeelding 2$$, 'inline'),
  ('8362dd36-1808-45f3-bde6-74b6c7a9c234', 'f582a769-7258-4d17-a9e0-be6f7de3b212', $$drie uitspraken over het gevolg van de modificatie van Gpr54$$,
   $$biologie-vwo-2025-ii-verouderende-eicellen-context8.png$$,
   $$Hieronder staan uitspraken over het gevolg van de modificatie van Gpr54.
1 In exon 1 treedt een frameshift-mutatie op.
2 Na translatie is het gevormde eiwit minstens 67 aminozuren korter.
3 De tertiaire structuur van het gevormde eiwit is veranderd. Schrijf de nummers 1, 2 en 3 onder elkaar. Noteer erachter of de$$, 'inline'),
  ('b1896e18-57e6-4888-ba47-f21c666e7c96', 'f582a769-7258-4d17-a9e0-be6f7de3b212', $$informatiekader: werkwijze (stap 1 t/m 4) om homozygote Gpr54-knock-out muizen te verkrijgen$$,
   $$biologie-vwo-2025-ii-verouderende-eicellen-context9.png$$,
   $$Om een groep van 30 homozygote Gpr54-knock-out muizen (Gpr54⁻ Gpr54⁻) te verkrijgen werd de volgende werkwijze gevolgd: stap 1 Uit enkele (wildtype) vrouwtjesmuizen werden bevruchte eicellen weggenomen. stap 2 De bevruchte eicellen kregen de crispr-behandeling. stap 3 Heterozygote bevruchte eicellen (Gpr54⁺Gpr54⁻) werden ingebracht bij draagmoedermuizen. stap 4 Toen de nakomelingen die hieruit ontstonden (F1) volwassen waren, werden ze onderling gekruist. Hieruit ontstond een F2.$$, 'inline'),
  ('3ee1f7ae-4fef-4527-9d84-c248b0f2c620', 'f582a769-7258-4d17-a9e0-be6f7de3b212', $$bij de crispr-behandeling ontstonden ook homozygote Gpr54−Gpr54− bevruchte eicellen$$,
   $$biologie-vwo-2025-ii-verouderende-eicellen-context10.png$$,
   $$Bij de crispr-behandeling (stap 2) ontstonden ook enkele bevruchte eicellen met het genotype Gpr54⁻ Gpr54⁻. Licht toe waarom deze niet gebruikt konden worden voor stap 3 en 4.$$, 'inline'),
  ('2483a9f8-0b08-4ac3-924b-616986a3085c', 'f582a769-7258-4d17-a9e0-be6f7de3b212', $$informatiekader: behandeling van de drie groepen gedurende 14 maanden (afbeelding 3)$$,
   $$biologie-vwo-2025-ii-verouderende-eicellen-context11.png$$,
   $$Afbeelding 3 toont de behandeling van de drie groepen vrouwtjesmuizen gedurende 14 maanden. Om het aantal chromosomale afwijkingen te bepalen, werden na twee maanden (2 m) en na veertien maanden (14 m) eicellen uit de eierstokken afgenomen bij alle vrouwtjesmuizen.
afbeelding 3$$, 'inline'),
  ('a82449ae-ef25-4655-b759-d6a28971adf9', 'f582a769-7258-4d17-a9e0-be6f7de3b212', $$in elke groep was een controle aanwezig$$,
   $$biologie-vwo-2025-ii-verouderende-eicellen-context12.png$$,
   $$In elke groep was een controle aanwezig (afbeelding 3).$$, 'inline'),
  ('dcabf892-5beb-4b90-8229-e85e74b158e2', 'f582a769-7258-4d17-a9e0-be6f7de3b212', $$drie vrouwen van 38 jaar met verschillende voorgeschiedenis van ovulatie-onderdrukking$$,
   $$biologie-vwo-2025-ii-verouderende-eicellen-context13.png$$,
   $$De onderzoeksresultaten wijzen erop dat een verminderd aantal ovulaties bij de muizenmoeder het aantal chromosomale afwijkingen in de eicellen vermindert. Als dit bij mensen ook geldt, zou dat voor vrouwen die op latere leeftijd kinderen willen, een reden kunnen zijn om hun ovulaties te onderdrukken. Hieronder zijn drie vrouwen van 38 jaar beschreven.
− Azra, gebruikt sinds haar puberteit een anticonceptiepil.
− Bernadien, heeft zes kinderen gekregen en gebruikte nooit een anticonceptiepil.
− Claire, heeft een verstopping van de eileiders, is voor het eerst zwanger na een ivf-behandeling en gebruikte nooit een anticonceptiepil. Welke vrouw zal de meeste ovulaties gehad hebben? En welke vrouw de$$, 'inline'),
  ('bacee157-4359-4fbb-b8a6-6bc80a54f170', 'fbe79bbd-ecbd-4bbb-abd0-0563a0a87e38', $$inleiding: Ellen heeft de ziekte van Graves en is zwanger van haar eerste kind$$,
   $$biologie-vwo-2025-ii-zwanger-met-de-ziekte-van-graves-context1.png$$,
   $$Ellen heeft al vanaf haar dertiende de ziekte van Graves. Zij wordt daarvoor behandeld door haar huisarts. Ellen is nu 29 en is net in verwachting van haar eerste kind. Ze overlegt met haar huisarts wat de gevolgen zijn voor haar zwangerschap en de behandeling van haar ziekte.$$, 'inline'),
  ('016d3899-6edf-4e41-aa18-917573018ca1', 'fbe79bbd-ecbd-4bbb-abd0-0563a0a87e38', $$informatiekader: ziekte van Graves ontstaat door IgG-antistof die de TSH-receptor activeert (afbeelding 1); behandeling met methimazol en T4-pillen$$,
   $$biologie-vwo-2025-ii-zwanger-met-de-ziekte-van-graves-context2.png$$,
   $$De ziekte van Graves is een auto-immuunziekte die ontstaat doordat een infectie door het afweersysteem is bestreden met een bepaalde IgG- antistof. Deze IgG-antistof activeert bij sommige mensen ook de TSH- receptor op de schildklier waardoor er extra veel afbeelding 1 schildklierhormoon (T4) wordt afgegeven (afbeelding 1). De symptomen die optreden zijn: een vergrote schildklier, gewichtsverlies, een verhoogde hartslagfrequentie, een verhoogde ademhalings- frequentie en het snel warm hebben. Om de verhoogde vorming van T4 te verhinderen slikt Ellen pillen met methimazol. Deze stof blokkeert de vorming van T4. Om ervoor te zorgen dat er geen tekort aan T4 ontstaat, slikt Ellen ook T4-pillen.$$, 'inline'),
  ('7812d919-e692-4f44-9994-e05cf3684b71', 'fbe79bbd-ecbd-4bbb-abd0-0563a0a87e38', $$verhoogde T4-afgifte verhoogt de ademhalingsfrequentie$$,
   $$biologie-vwo-2025-ii-zwanger-met-de-ziekte-van-graves-context3.png$$,
   $$Bij iemand met een verhoogde T4-afgifte is de ademhalingsfrequentie verhoogd, doordat het ademcentrum sterker wordt gestimuleerd.$$, 'inline'),
  ('87603cdf-f443-4f99-ba11-a94d448c099d', 'fbe79bbd-ecbd-4bbb-abd0-0563a0a87e38', $$TSH en TRH houden de T4-concentratie op peil bij een gezond persoon$$,
   $$biologie-vwo-2025-ii-zwanger-met-de-ziekte-van-graves-context4.png$$,
   $$TSH en TRH zijn hormonen die de T4-concentratie in een gezonde persoon op peil houden. Zal de TSH-concentratie in het bloed van Ellen voorafgaand aan de$$, 'inline'),
  ('fb27e9ff-f0fe-47d2-9288-7b1ebbb5e58f', 'fbe79bbd-ecbd-4bbb-abd0-0563a0a87e38', $$informatiekader: T3 bindt aan het T3-responsief element (TRE) en beïnvloedt methylering en acetylering van genen (afbeelding 2)$$,
   $$biologie-vwo-2025-ii-zwanger-met-de-ziekte-van-graves-context5.png$$,
   $$In de lichaamscellen wordt T4 door een enzym omgezet in T3. Genen die gevoelig zijn voor regulatie door T3 bevatten een korte sequentie: het T3-responsief element (TRE). T3 bindt aan een receptor-co-repressor- complex dat is gebonden aan het TRE, waardoor de vorm van dit complex verandert en de repressor loslaat. Daarna wordt, door binding van een activator, het co-activator-complex gevormd, waarna de genexpressie begint (afbeelding 2). De binding van T3 aan het TRE verandert ook de methylering en acetylering van de door T3 gereguleerde genen.
afbeelding 2$$, 'inline'),
  ('60c2d677-c396-499d-9f47-15ebebd33268', 'fbe79bbd-ecbd-4bbb-abd0-0563a0a87e38', $$drie uitspraken over T3 en de invloed van T3 op genexpressie$$,
   $$biologie-vwo-2025-ii-zwanger-met-de-ziekte-van-graves-context6.png$$,
   $$Hieronder staan uitspraken over T3 en de invloed van T3 op genexpressie.
1 T3 is een eiwit.
2 Het TRE is onderdeel van het coderend DNA van het T3-gevoelig gen.
3 In aanwezigheid van T3 is er meer ruimte rondom het histon, waardoor polymerase kan binden. Schrijf de nummers 1, 2 en 3 onder elkaar. Noteer erachter of de$$, 'inline'),
  ('dcfc02e4-24cd-4c07-a1ed-19f4d0da58fb', 'fbe79bbd-ecbd-4bbb-abd0-0563a0a87e38', $$informatiekader: tijdens de zwangerschap verandert de vouwing van nieuw gevormde IgG-eiwitten$$,
   $$biologie-vwo-2025-ii-zwanger-met-de-ziekte-van-graves-context7.png$$,
   $$De huisarts vertelt Ellen dat ze tijdens haar zwangerschap vaker haar T4- concentratie zal controleren. Door de veranderingen in haar lichaam als gevolg van de zwangerschap zal Ellen steeds minder medicijnen hoeven slikken. De hoeveelheid ‘verstorende’ IgG in het bloed van Ellen zal afnemen doordat de vouwing van de nieuw gevormde IgG-eiwitten verandert als gevolg van de zwangerschap. Zodra Ellen bevallen is, zullen de symptomen van de ziekte van Graves terugkomen en zal Ellen wel weer de hogere dosis medicijnen moeten gebruiken.$$, 'inline'),
  ('9492754c-c7ca-4119-a600-f78e6ea834eb', 'fbe79bbd-ecbd-4bbb-abd0-0563a0a87e38', $$veranderde structuur van het IgG vermindert de symptomen van de ziekte van Graves$$,
   $$biologie-vwo-2025-ii-zwanger-met-de-ziekte-van-graves-context8.png$$,
   $$Door de veranderde structuur van het IgG verminderen de symptomen van de ziekte van Graves.$$, 'inline'),
  ('9e39ea94-a9f8-4cc0-8280-a072e71368a5', 'fbe79bbd-ecbd-4bbb-abd0-0563a0a87e38', $$een vergrote schildklier bij de foetus wijst op een te hoge T4-concentratie bij de foetus$$,
   $$biologie-vwo-2025-ii-zwanger-met-de-ziekte-van-graves-context9.png$$,
   $$Na twintig weken krijgt Ellen een echo-onderzoek. De echografist kijkt hierbij ook of de schildklier van de foetus is vergroot. Een vergrote schildklier is een indicatie dat de T4-concentratie bij de foetus te hoog is. Verklaar waardoor een vergrote schildklier bij de foetus zou zijn ontstaan.$$, 'inline'),
  ('5bed067b-7e3a-47eb-afbd-9bc4f302d962', 'fbe79bbd-ecbd-4bbb-abd0-0563a0a87e38', $$informatiekader: na acht maanden zwangerschap krijgt Ellen weer last van warmte en verhoogde ademhaling$$,
   $$biologie-vwo-2025-ii-zwanger-met-de-ziekte-van-graves-context10.png$$,
   $$Bij de 20 wekenecho worden geen afwijkingen gevonden bij de foetus. Na acht maanden zwangerschap is Ellen toch bezorgd. Ze heeft het namelijk sneller warm, en zelfs bij lichte inspanning wordt haar ademhalings- frequentie veel hoger. De T4-concentratie in het bloed van Ellen blijkt normaal te zijn. De huisarts legt uit dat de symptomen worden veroorzaakt door de aanwezigheid van de baby.$$, 'inline'),
  ('9dcf16fd-ed05-48c9-9139-e249b10784c8', 'fbe79bbd-ecbd-4bbb-abd0-0563a0a87e38', $$drie uitspraken die een mogelijke verklaring geven voor de symptomen van Ellen$$,
   $$biologie-vwo-2025-ii-zwanger-met-de-ziekte-van-graves-context11.png$$,
   $$Hieronder staan uitspraken die een mogelijke verklaring geven voor de symptomen van Ellen.
1 Haar ademhalingsfrequentie neemt toe doordat haar vitale capaciteit lager wordt.
2 Ze heeft het sneller warm doordat de hoeveelheid bloed toeneemt.
3 Ze heeft het sneller warm doordat de oppervlakte-inhoudsverhouding kleiner wordt.$$, 'inline'),
  ('20d69328-640f-44c4-8c76-98e91b80692e', '18f285f7-43cc-430e-b941-196e21a0931b', $$inleiding: jongen krijgt tijdens verblijf in Nederland epileptische aanvallen door een varkenslintworm$$,
   $$biologie-vwo-2025-ii-epilepsie-door-lintwormlarven-context1.png$$,
   $$Een zestienjarige jongen kreeg tijdens zijn verblijf in Nederland regelmatig epileptische aanvallen. Uit onderzoek bleek dat deze aanvallen het gevolg waren van een varkenslintworm.$$, 'inline'),
  ('0e0ece8c-3794-4db8-a950-79f16fed5d48', '18f285f7-43cc-430e-b941-196e21a0931b', $$informatiekader: epilepsie en de MRI-scan met cysten en oedeem (afbeelding 1, afbeelding 2)$$,
   $$biologie-vwo-2025-ii-epilepsie-door-lintwormlarven-context2.png$$,
   $$Epilepsie is een aandoening van het centrale zenuwstelsel waarbij af en toe een sterk afwijkende hersenactiviteit ontstaat: een epileptische aanval. Tijdens een epileptische aanval kunnen ongecontroleerde spiersamentrekkingen optreden, en kan de patiënt het bewustzijn verliezen. Op de MRI-scan van het hoofd van de jongen (afbeelding 1) zijn holtes (cysten) te zien. Eromheen is oedeem te zien (afbeelding 2).
afbeelding 1 afbeelding 2$$, 'inline'),
  ('354f44df-9ba4-4e53-afaa-e8ac5ab6ca80', '18f285f7-43cc-430e-b941-196e21a0931b', $$drie uitspraken over de MRI-scan$$,
   $$biologie-vwo-2025-ii-epilepsie-door-lintwormlarven-context3.png$$,
   $$Hieronder staan uitspraken over de MRI-scan (afbeelding 1, afbeelding 2).
1 Het oedeem bevindt zich in het hersengebied dat is betrokken bij het gezichtsvermogen.
2 Al het hersenweefsel dat te zien is op de scan, behoort tot de grijze stof.
3 Het hersengebied dat de slikreflex aanstuurt, is zichtbaar op de scan. Schrijf de nummers 1, 2 en 3 onder elkaar. Noteer erachter of de$$, 'inline'),
  ('4a3c9d2e-724f-4d49-bbc5-19d5dc3fba97', '18f285f7-43cc-430e-b941-196e21a0931b', $$acetylcholine-afgifte bij spiersamentrekking; drie uitspraken over productie, afgifte en werking$$,
   $$biologie-vwo-2025-ii-epilepsie-door-lintwormlarven-context4.png$$,
   $$Bij spiersamentrekkingen geven de eindplaatjes van motorische neuronen acetylcholine af. Hieronder staan uitspraken over de productie, afgifte en werking van acetylcholine.
1 Het enzym dat acetaat en choline omzet in acetylcholine, wordt vanuit het cellichaam naar het motorisch eindplaatje vervoerd.
2 Acetylcholine wordt afgegeven als gevolg van de instroom van calciumionen.
3 Binding van acetylcholine aan de receptoren op de postsynaptische membraan leidt tot hyperpolarisatie van die membraan. Schrijf de nummers 1, 2 en 3 onder elkaar. Noteer erachter of de$$, 'inline'),
  ('8a2213a2-3dfa-4991-8183-3356ff15dd8c', '18f285f7-43cc-430e-b941-196e21a0931b', $$informatiekader: bouw van de varkenslintworm Taenia solium (afbeelding 3)$$,
   $$biologie-vwo-2025-ii-epilepsie-door-lintwormlarven-context5.png$$,
   $$De jongen werd uitgebreid onderzocht door een medisch parasitoloog. Hij stelde de diagnose: neurocysticercose. Deze aandoening wordt veroorzaakt door de varkenslintworm (Taenia solium, afbeelding 3), een parasitaire worm waarvan de mens de enige eindgastheer is. Zowel de mens als het varken is tussengastheer. De larven bevinden zich in cysten in weefsels van de afbeelding 3 gastheer. Een volwassen varkenslintworm leeft in de dunne darm. Hij kan tot acht meter lang worden en heeft een plat lichaam. Zijn kop heeft zuignappen waarmee hij zich vasthecht aan de wand van de dunne darm. De worm heeft geen mond of spijsverterings- kanaal.$$, 'inline'),
  ('be753ede-8dbf-4160-90e8-496b190c8bbc', '18f285f7-43cc-430e-b941-196e21a0931b', $$twee manieren van infectie met de lintworm; schema levenscyclus van Taenia solium met plaatsen P, Q, R en S$$,
   $$biologie-vwo-2025-ii-epilepsie-door-lintwormlarven-context6.png$$,
   $$Mensen kunnen op twee manieren geïnfecteerd raken met de lintworm. Hieronder staat een schema van de levenscyclus van Taenia solium. Op de plaatsen P, Q, R en S ontbreken woorden.$$, 'inline'),
  ('ad4b4754-7a65-438a-9c40-ce04915f4db5', '18f285f7-43cc-430e-b941-196e21a0931b', $$informatiekader: albendazol remt fumaraatreductase (FRD); elektronentransportketen bij mens en lintworm (afbeelding 4)$$,
   $$biologie-vwo-2025-ii-epilepsie-door-lintwormlarven-context7.png$$,
   $$De parasitoloog schreef het medicijn albendazol voor. Albendazol doodt lintwormlarven doordat het een remmende werking heeft op fumaraatreductase (FRD). Normaal zet FRD in de mitochondriën van varkenslintwormlarven fumaarzuur om in barnsteenzuur. Deze omzetting is cruciaal voor de energievoorziening. Afbeelding 4 toont de oxidatieve fosforylering bij de mens, en de elektronentransportketen bij de lintworm, die in anaerobe omstandigheden leeft. Hierin is ook het effect van albendazol aangegeven.
afbeelding 4$$, 'inline'),
  ('47fcdc47-968d-4f32-93a6-d804abb5675f', '18f285f7-43cc-430e-b941-196e21a0931b', $$eiwitcomplex II (SQR) heeft bij de mens ook een functie in de citroenzuurcyclus$$,
   $$biologie-vwo-2025-ii-epilepsie-door-lintwormlarven-context8.png$$,
   $$Bij de mens heeft eiwitcomplex II (SQR) ook een functie in de citroenzuurcyclus, waar het barnsteenzuur omzet.$$, 'inline'),
  ('3a4ee66a-d505-4dfe-b655-cd6bfbbaef36', '18f285f7-43cc-430e-b941-196e21a0931b', $$invultekst: effect van albendazol op de elektronentransportketen in de varkenslintworm$$,
   $$biologie-vwo-2025-ii-epilepsie-door-lintwormlarven-context9.png$$,
   $$De tekst hieronder beschrijft het effect van albendazol op de elektronentransportketen in een varkenslintworm. Op vier plaatsen ontbreekt een woord.
Albendazol remt FRD, waardoor de omzetting van fumaarzuur verhinderd wordt. Fumaarzuur dient als …(1)… , en heeft dezelfde functie als …(2)… bij de oxidatieve fosforylering in de mens. Door remming van FRD wordt voorkomen dat NADH elektronen kan afstaan en ontstaat er geen gradiënt van …(3)… Hierdoor wordt uiteindelijk de productie van …(4)… geremd.$$, 'inline'),
  ('804e3428-bb9b-42f5-9461-e109cdcc135d', '18f285f7-43cc-430e-b941-196e21a0931b', $$na behandeling met albendazol nam de frequentie van epileptische aanvallen af maar verdween niet volledig$$,
   $$biologie-vwo-2025-ii-epilepsie-door-lintwormlarven-context10.png$$,
   $$Na de behandeling met albendazol waren de lintwormen gedood. Hierdoor nam bij de jongen de frequentie van epileptische aanvallen af, maar ze verdwenen niet volledig.$$, 'inline'),
  ('954fc413-292e-42e2-b8c6-c4debc67c800', 'ae259671-b48f-4dc6-bc51-96cc73ba0b49', $$inleiding: onderzoek naar de snelheid van verdwerging bij olifanten op Sicilië$$,
   $$biologie-vwo-2025-ii-dwergolifanten-op-sicilie-context1.png$$,
   $$Op eilanden hebben veel zoogdiersoorten een afwijkende grootte vergeleken met verwante soorten op het vasteland. Grote soorten zijn er kleiner, kleine soorten zijn er groter. Een team van wetenschappers heeft aan de hand van fossielen een schatting gemaakt van de snelheid van ‘verdwerging’ bij olifanten die leefden op Sicilië.$$, 'inline'),
  ('bbcec883-820d-490c-a7ca-f35dc49366ff', 'ae259671-b48f-4dc6-bc51-96cc73ba0b49', $$informatiekader: de wet van Foster over verreuzing en verdwerging op eilanden (afbeelding 1)$$,
   $$biologie-vwo-2025-ii-dwergolifanten-op-sicilie-context2.png$$,
   $$De ‘verreuzing’ en ‘verdwerging’ van zoogdiersoorten die eilanden koloniseren, wordt de wet van Foster genoemd (afbeelding 1). Bij de ontwikkeling richting de afwijkende afmetingen zijn verschillende factoren betrokken. Wetenschappers veronderstellen dat na vestiging eerst een sterke populatiegroei plaatsvindt, en daarna de ontwikkeling naar een optimale grootte van de individuen.
afbeelding 1$$, 'inline'),
  ('f733fef7-eb47-42b7-9c87-b60e01c77c2c', 'ae259671-b48f-4dc6-bc51-96cc73ba0b49', $$drie uitspraken over de genetische samenstelling van een nieuw-gevestigde eilandpopulatie$$,
   $$biologie-vwo-2025-ii-dwergolifanten-op-sicilie-context3.png$$,
   $$De genetische samenstelling van een nieuw-gevestigde eilandpopulatie is anders dan die van de oorspronkelijke populatie van het vasteland. Hieronder staan uitspraken over dit verschil.
1 Er is sprake van het foundereffect.
2 Door de isolatie van de populatie op het eiland treedt gene flow op.
3 De genenpool van de eilandpopulatie is kleiner dan die van het vasteland.$$, 'inline'),
  ('347a03cd-1547-4a2c-8ba2-7b6052c3d9a6', 'ae259671-b48f-4dc6-bc51-96cc73ba0b49', $$verreuzing of verdwerging door natuurlijke selectie kan leiden tot een aparte soort$$,
   $$biologie-vwo-2025-ii-dwergolifanten-op-sicilie-context4.png$$,
   $$De verreuzing of verdwerging van zoogdieren op eilanden wordt veroorzaakt door natuurlijke selectie. Uiteindelijk kan de populatie op het eiland een aparte soort worden.$$, 'inline'),
  ('b410af83-adb8-46bf-9668-896f631aeb19', 'ae259671-b48f-4dc6-bc51-96cc73ba0b49', $$eilandtheorie van McArthur en Wilson over aantal soorten op een eiland$$,
   $$biologie-vwo-2025-ii-dwergolifanten-op-sicilie-context5.png$$,
   $$De verdwerging van grote zoogdieren op een gekoloniseerd eiland is mede te verklaren met de eilandtheorie van McArthur en Wilson. Een kleiner aantal soorten op een eiland maakt de kans groter dat predatoren afwezig zijn. Grote zoogdiersoorten kunnen dan verdwergen.$$, 'inline'),
  ('84c42a71-de99-422e-908e-51c28b40110c', 'ae259671-b48f-4dc6-bc51-96cc73ba0b49', $$informatiekader: fossiele resten van de puntali-olifant en de Europese bosolifant; mtDNA-onderzoek (afbeelding 2)$$,
   $$biologie-vwo-2025-ii-dwergolifanten-op-sicilie-context6.png$$,
   $$De wetenschappers onderzochten fossiele resten van de puntali-olifant (Palaeoloxodon mnaidriensis), een uitgestorven olifantensoort die leefde op het Italiaanse eiland Sicilië. Deze dwergolifant is een afstammeling van de veel grotere uitgestorven Europese bosolifant (Palaeoloxodon antiquus) die 781.000 tot 30.000 jaar geleden leefde. Zie afbeelding 2.
afbeelding 2
De wetenschappers konden mitochondriaal DNA (mtDNA) isoleren uit een fossiel bot uit het binnenoor van een puntali-olifant. Dit mtDNA werd gebruikt om de lengte van de periode van verdwerging te bepalen.$$, 'inline'),
  ('63ef6fc3-7980-477e-80e8-afed14c7dd27', 'ae259671-b48f-4dc6-bc51-96cc73ba0b49', $$mtDNA moest eerst vermenigvuldigd worden voordat de basevolgorde bepaald kon worden$$,
   $$biologie-vwo-2025-ii-dwergolifanten-op-sicilie-context7.png$$,
   $$Voor het onderzoek moest het mtDNA eerst worden vermenigvuldigd, waarna de basevolgorde ervan kon worden bepaald.
−$$, 'inline'),
  ('22cb9473-92d6-443c-ba1e-652a42184fc5', 'ae259671-b48f-4dc6-bc51-96cc73ba0b49', $$informatiekader: datering van de fossielen van de puntali-olifant (afbeelding 3)$$,
   $$biologie-vwo-2025-ii-dwergolifanten-op-sicilie-context8.png$$,
   $$Met behulp van de DNA-gegevens werd een schatting gemaakt van de periode waarin de verdwerging plaatsvond. De gevonden fossielen van de puntali-olifant worden als het eindstadium van het verdwergingsproces beschouwd. De ouderdom van deze fossielen ligt tussen 175.500 en 50.000 jaar. Zie afbeelding 3.
afbeelding 3$$, 'inline'),
  ('d574b4e9-4022-4644-a2ac-cfcbf3691d97', 'ae259671-b48f-4dc6-bc51-96cc73ba0b49', $$berekening van de laagst mogelijke snelheid van verdwerging$$,
   $$biologie-vwo-2025-ii-dwergolifanten-op-sicilie-context9.png$$,
   $$De onderzoekers schrijven dat de hoogst mogelijke snelheid van verdwerging 41,5 mm per generatie was. Met de gegevens in afbeelding 3 is de laagst mogelijke snelheid van verdwerging per generatie te berekenen. Ga uit van een generatietijd van
31 jaar. Wat is deze laagst mogelijke snelheid van verdwerging?$$, 'inline');

insert into practice_questions (id, exercise_id, question_number, topics, keywords, question_summary, question_image_url, question_text, context_block_ids) values
  ('c83e8735-b4c1-4e73-a6af-f33047cb645a', '1577ca6a-6e0b-45a7-963d-5791c1ce2a96', 1,
   '[{"domain": "Orgaan- en organismeniveau", "subdomain": "Stofwisseling van het organisme"}]'::jsonb,
   '["maagverkleiningsoperatie", "dunne darm", "alvleesklier-enzymen", "voedingsopname", "gewichtsverlies"]'::jsonb,
   $$Verklaren van oorzaken van gewichtsverlies na een maagverkleiningsoperatie.$$,
   $$biologie-vwo-2025-ii-een-brouwerij-in-de-darmen-vraag1.png$$, $$2p 1 Geef twee van deze oorzaken.$$, array['4c53767e-ad8b-43b1-8cf4-b66518d24891', 'e595adab-f955-4883-bd39-b186c0662eda', '23ee8d73-9aee-47ca-b70a-e851aad517fe']::uuid[]),
  ('79edadcb-8dea-4a1a-910f-246a1d3199bc', '1577ca6a-6e0b-45a7-963d-5791c1ce2a96', 2,
   '[{"domain": "Orgaan- en organismeniveau", "subdomain": "Stofwisseling van het organisme"}]'::jsonb,
   '["emulgeren van vetten", "gal", "alvleesklierenzymen", "spijsvertering van vetten"]'::jsonb,
   $$Verklaren dat het emulgeren van vetten na de maagverkleiningsoperatie nog mogelijk is.$$,
   $$biologie-vwo-2025-ii-een-brouwerij-in-de-darmen-vraag2.png$$, $$1p 2 Verklaar dat na de operatie het emulgeren van vetten nog steeds kan plaatsvinden.$$, array['e595adab-f955-4883-bd39-b186c0662eda']::uuid[]),
  ('a1dcb8dd-1b6c-4a66-a89e-9fa1dd2bad56', '1577ca6a-6e0b-45a7-963d-5791c1ce2a96', 3,
   '[{"domain": "Orgaan- en organismeniveau", "subdomain": "Zelfregulatie van het organisme"}]'::jsonb,
